def transform(grid):
    # Keep the grid except draw a vertical 8 stripe immediately right of the
    # separator line of 2s. Demonstrations preserve the object pattern as-is.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sep = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if sep is not None and sep + 1 < w:
        for r in range(h):
            out[r][sep + 1] = 8
    return out

